def svg(kind, accent, label=''):
    shape = SHAPES[kind].replace('{accent}', accent)
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="720" height="440" viewBox="0 0 360 220" role="img"><title>{escape(label)}</title><defs><linearGradient id="bg" x2="1" y2="1"><stop stop-color="#f6fafc"/><stop offset="1" stop-color="#e4eef5"/></linearGradient><linearGradient id="body" x2=".7" y2="1"><stop stop-color="#ffffff"/><stop offset=".5" stop-color="#eaf2f7"/><stop offset="1" stop-color="#cddfe9"/></linearGradient><filter id="shadow" x="-30%" y="-30%" width="160%" height="170%"><feDropShadow dx="0" dy="9" stdDeviation="6" flood-color="#294b64" flood-opacity=".13"/></filter></defs><rect width="360" height="220" rx="16" fill="url(#bg)"/><circle cx="183" cy="107" r="89" fill="white" opacity=".55"/><ellipse cx="180" cy="201" rx="106" ry="8" fill="#779eb8" opacity=".12"/><g filter="url(#shadow)" font-family="Segoe UI,sans-serif" fill="#284d5d">{shape}</g></svg>'''

def generate(source):
    text = Path(source).read_text(encoding='utf-8')
    devices = []
    for index, (cat, title, description, tagline, accent) in enumerate(CATEGORIES):
        section = text.split(f'# {index+9}. CATEGORY')[1].split('\n---')[0]
        names = re.findall(r'^\d+\. (.+)$', section, re.M)
        profiles = ASSIGNMENTS[index].split()
        assert len(names) == len(profiles), (cat, len(names), len(profiles))
        for name, profile in zip(names, profiles):
            name = name.strip()
            kind, summary, flow = PROFILES[profile]
            if name in OVERRIDES:
                summary, flow, art_kind = OVERRIDES[name]
                kind = art_kind or kind
            device_slug = {'ECG Machine':'ecg', 'TV Remote Control':'tv-remote', 'Fly-by-Wire System':'fly-by-wire', 'Automatic Identification System (AIS)':'ais'}.get(name, slug(name))
            identifier = cat + '/' + device_slug
            filename = f'{cat}-{device_slug}.svg'
            ART.joinpath(filename).write_text(svg(kind, accent, name), encoding='utf-8')
            stages = flow.split('|')
            introduction = f'{summary} The {name} signal path begins with {stages[0].lower()} and leads to {stages[-1].lower()}. Between these endpoints, {", ".join(stages[1:-1]).lower()} connect the physical system to its digital processing and output.'
            implemented = name in re.findall(r'^ \[\d+,"([^"]+)"', (OUT/'labs/data.ts').read_text(encoding='utf-8'), re.M) if (OUT/'labs/data.ts').exists() else False
            devices.append(dict(id=identifier, slug=device_slug, name=name, category=cat, categories=[cat], shortDescription=summary, longDescription=introduction, thumbnail='/devices/'+filename, status='available' if implemented else 'upcoming', keywords=[profile, kind, *flow.lower().split('|')], signalFlow=flow.split('|'), futureFeatures=['anatomy','signal','logic','waveforms','simulation','failure']))
    categories = [dict(id=c, name=n, description=d, tagline=t, accent=a) for c,n,d,t,a in CATEGORIES]
    definitions = '''export type DeviceCategory = "medical" | "aviation" | "defence" | "marine" | "robotics" | "everyday";
export type DeviceStatus = "upcoming" | "available" | "beta";
export type FeatureId = "anatomy" | "signal" | "logic" | "waveforms" | "simulation" | "failure";
export interface Device { id: string; slug: string; name: string; category: DeviceCategory; categories: DeviceCategory[]; shortDescription: string; longDescription: string; thumbnail: string; status: DeviceStatus; keywords: string[]; signalFlow: string[]; futureFeatures: FeatureId[] }
export interface Category { id: DeviceCategory; name: string; description: string; tagline: string; accent: string }
export const STUDIO_PATH = "/studios/how-devices-work";
export const devicePath = (device: Device) => `${STUDIO_PATH}/${device.category}/${device.slug}`;
'''
    OUT.joinpath('catalogue.ts').write_text(definitions+'export const CATEGORIES: Category[] = '+json.dumps(categories,indent=2,ensure_ascii=False)+';\nexport const DEVICES: Device[] = '+json.dumps(devices,indent=2,ensure_ascii=False)+''';
export function findDevice(category: string | undefined, slug: string | undefined) { return DEVICES.find(device => device.category === category && device.slug === slug); }
export function searchDevices(query: string, category?: string) { const terms = query.toLowerCase().trim().split(/\\s+/).filter(Boolean); return DEVICES.filter(device => (!category || device.categories.some(id => id === category)) && terms.every(term => [device.name, ...CATEGORIES.filter(item => device.categories.includes(item.id)).map(item => item.name), ...device.keywords].join(" ").toLowerCase().includes(term))); }
export const FEATURES: Record<FeatureId, {title: string; description: string}> = {
 anatomy: { title: "Device Anatomy", description: "Explore the major internal modules." },
 signal: { title: "Signal Journey", description: "Trace signals through the system." },
 logic: { title: "Digital Logic", description: "See how data becomes binary and is processed." },
 waveforms: { title: "Waveforms", description: "Inspect important signals and timing." },
 simulation: { title: "Interactive Simulation", description: "Change inputs and observe system behaviour." },
 failure: { title: "Failure Explorer", description: "Discover what happens when key components fail." },
};
const RELATED: Record<string, string[]> = {
 "medical/mri-scanner": ["ct-scanner", "pet-scanner", "ultrasound-scanner", "x-ray-machine"],
 "everyday/tv-remote": ["television", "ir-camera", "nfc-payment-system", "smartphone"],
 "aviation/aircraft-autopilot": ["aircraft-flight-computer", "fly-by-wire", "air-data-computer", "inertial-navigation-system"],
};
export function relatedDevices(device: Device) {
 const preferred = RELATED[device.id];
 if (preferred) return preferred.map(slug => DEVICES.find(item => item.slug === slug && item.categories.includes(device.category))).filter((item): item is Device => Boolean(item));
 return DEVICES.filter(item => item.id !== device.id && item.categories.some(category => device.categories.includes(category))).sort((a, b) => Number(b.keywords[0] === device.keywords[0]) - Number(a.keywords[0] === device.keywords[0])).slice(0, 4);
}
''',encoding='utf-8')
    # A local composition uses the same equipment artwork as the cards.
    placements = [('mri',30,24,.74),('cockpit',285,15,.65),('arm',342,153,.72),('ecg',0,161,.62),('nfc',183,142,.64)]
    groups = ''.join(f'<g transform="translate({x} {y}) scale({scale})">{SHAPES[k].replace("{accent}", "#458b99")}</g>' for k,x,y,scale in placements)
    ART.joinpath('studio-collection.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" width="1100" height="680" viewBox="0 0 550 340"><defs><linearGradient id="body" x2=".7" y2="1"><stop stop-color="#fff"/><stop offset="1" stop-color="#bfd5e3"/></linearGradient><filter id="s"><feDropShadow dx="0" dy="9" stdDeviation="7" flood-color="#294b64" flood-opacity=".14"/></filter></defs><circle cx="265" cy="155" r="150" fill="#eaf3f8"/><circle cx="265" cy="155" r="116" fill="none" stroke="#d2e4ee" stroke-dasharray="3 8"/><g filter="url(#s)" font-family="Segoe UI,sans-serif" fill="#284d5d">{groups}</g></svg>',encoding='utf-8')
    print(f'Generated {len(devices)} devices across {len(categories)} categories.')

if __name__ == '__main__':
    import sys
